from subtotal import subtotal


def potongan(jumlah_boks):
    if jumlah_boks >= 100:
        return 0.12
    elif jumlah_boks >= 50:
        return 0.08
    else:
        return 0.0


def total_bayar(jumlah_boks, harga_satuan):
    kotor = subtotal(jumlah_boks, harga_satuan)
    return kotor - kotor * potongan(jumlah_boks)

