def baris_struk(nama, jumlah, harga_satuan):
    return f"{nama} x{jumlah} {format_rupiah(total_bayar(jumlah, harga_satuan))}"


def buat_struk(isi):
    baris = ["STRUK UD RASA GRESIK"]
    total = 0
    for nama, jumlah, harga in isi:
        baris.append(baris_struk(nama, jumlah, harga))
        total += total_bayar(jumlah, harga)
    baris.append("TOTAL " + format_rupiah(total))
    return "\n".join(baris)

