        self.harga = harga


class Keranjang:
    def __init__(self):
        self.isi = []

    def tambah(self, barang, jumlah):
        self.isi.append((barang, jumlah))

    def hapus(self, nama):
        for i, (barang, jumlah) in enumerate(self.isi):
            if barang.nama == nama:
                del self.isi[i]
                return True
        return False

    def total(self):
        jumlah_total = 0
        for barang, jumlah in self.isi:
            jumlah_total += total_bayar(jumlah, barang.harga)
        return jumlah_total

    def __len__(self):
        return len(self.isi)

