def simpan(keranjang, nama_berkas):
    data = []
    for barang, jumlah in keranjang.isi:
        data.append({"nama": barang.nama, "harga": barang.harga, "jumlah": jumlah})
    with open(nama_berkas, "w") as f:
        json.dump(data, f)


def muat(nama_berkas):
    keranjang = Keranjang()
    try:
        with open(nama_berkas) as f:
            data = json.load(f)
    except FileNotFoundError:
        return keranjang
    for d in data:
        keranjang.tambah(Barang(d["nama"], d["harga"]), d["jumlah"])
    return keranjang

