# cari_urut.py

def urutkan_harga(daftar):
    hasil = list(daftar)
    n = len(hasil)
    for i in range(n):
        for j in range(n - 1 - i):
            if hasil[j][1] > hasil[j + 1][1]:
                hasil[j], hasil[j + 1] = hasil[j + 1], hasil[j]
    return hasil


def cari_linear(daftar, nama):
    for i in range(len(daftar)):
        if daftar[i][0] == nama:
            return i
    return -1


def cari_biner(daftar_terurut, harga):
    kiri = 0
    kanan = len(daftar_terurut) - 1
    while kiri <= kanan:
        tengah = (kiri + kanan) // 2
        h = daftar_terurut[tengah][1]
        if h == harga:
            return tengah
        elif h < harga:
            kiri = tengah + 1
        else:
            kanan = tengah - 1
    return -1

